    "/mod_forum_update_discussion_post": {
      post: {
        operationId: "mod_forum_update_discussion_post",
        summary: "Updates a post or a discussion topic post.",
        description: "Updates a post or a discussion topic post.",
        requestBody: {
          content: {
            "application/json": {
              schema: {
                type: "object",
                properties: {
                  postid: {
                    description: "Post to be updated. It can be a discussion topic post.",
                    type: "integer"
                  },
                  subject: {
                    description: "Updated post subject",
                    type: "string",
                    default: "",
                    nullable: true
                  },
                  message: {
                    description: "Updated post message (HTML assumed if messageformat is not provided)",
                    type: "string",
                    default: "",
                    nullable: true
                  },
                  messageformat: {
                    description: "message format (1 = HTML, 0 = MOODLE, 2 = PLAIN, or 4 = MARKDOWN)",
                    type: "integer",
                    default: "1",
                    nullable: true
                  },
                  options: {
                    description: "The allowed keys (value format) are: \n- `pinned` (bool); only for discussions) whether to pin this discussion or not\n- `discussionsubscribe` (bool); whether to subscribe to the post or not\n- `inlineattachmentsid` (int); the draft file area id for inline attachments in the text\n- `attachmentsid` (int); the draft file area id for attachments",
                    type: "array",
                    items: {
                      oneOf: [
                        {
                          type: "object",
                          properties: {
                            name: {
                              description: "only for discussions) whether to pin this discussion or not",
                              type: "string",
                              enum: [
                                "pinned"
                              ]
                            },
                            value: {
                              description: "bool",
                              type: "boolean"
                            }
                          },
                          required: [
                            "name",
                            "value"
                          ]
                        },
                        {
                          type: "object",
                          properties: {
                            name: {
                              description: "whether to subscribe to the post or not",
                              type: "string",
                              enum: [
                                "discussionsubscribe"
                              ]
                            },
                            value: {
                              description: "bool",
                              type: "boolean"
                            }
                          },
                          required: [
                            "name",
                            "value"
                          ]
                        },
                        {
                          type: "object",
                          properties: {
                            name: {
                              description: "the draft file area id for inline attachments in the text",
                              type: "string",
                              enum: [
                                "inlineattachmentsid"
                              ]
                            },
                            value: {
                              description: "int",
                              type: "number"
                            }
                          },
                          required: [
                            "name",
                            "value"
                          ]
                        },
                        {
                          type: "object",
                          properties: {
                            name: {
                              description: "the draft file area id for attachments",
                              type: "string",
                              enum: [
                                "attachmentsid"
                              ]
                            },
                            value: {
                              description: "int",
                              type: "number"
                            }
                          },
                          required: [
                            "name",
                            "value"
                          ]
                        }
                      ]
                    }
                  }
                },
                required: [
                  "postid"
                ]
              }
            }
          }
        },
        responses: {
          "200": {
            description: "Successful response",
            content: {
              "application/json": {
                schema: {
                  type: "object",
                  properties: {
                    status: {
                      description: "True if the post/discussion was updated, false otherwise.",
                      type: "boolean"
                    },
                    warnings: {
                      type: "array",
                      items: {
                        type: "object",
                        properties: {
                          item: {
                            description: "item",
                            type: "string",
                            nullable: true
                          },
                          itemid: {
                            description: "item id",
                            type: "integer",
                            nullable: true
                          },
                          warningcode: {
                            description: "the warning code can be used by the client app to implement specific behaviour",
                            type: "string"
                          },
                          message: {
                            description: "untranslated english message to explain the warning",
                            type: "string"
                          }
                        },
                        required: [
                          "warningcode",
                          "message"
                        ]
                      }
                    }
                  },
                  required: [
                    "status"
                  ]
                }
              }
            }
          },
          "400": {
            description: "Invalid parameter value detected",
            content: {
              "application/json": {
                schema: {
                  $ref: "#/components/schemas/ErrorResponse"
                }
              }
            }
          }
        },
        security: [
          {
            apiKey: []
          }
        ],
        tags: [
          "mod_forum",
          "write"
        ]
      }
    },
